export const schoolsDirectory: SchoolInfo[] = rawData.map(row => {
  const cct = String(row[7] || '');
  let mod = 'PES';
  if (cct.includes('DES')) mod = 'DES';
  else if (cct.includes('DST')) mod = 'DST';
  else if (cct.includes('DTV')) mod = 'DTV';
  
  return {
    region: String(row[0] || ''),
    valle: String(row[1] || ''),
    municipio: String(row[2] || ''),
    subsistema: String(row[3] || ''),
    control: String(row[4] || ''),
    nivel: String(row[5] || ''),
    servicioEducativo: String(row[6] || ''),
    cct: cct,
    turno: String(row[8] || ''),
    nombre: String(row[9] || ''),
    domicilio: String(row[10] || ''),
    localidad: String(row[11] || ''),
    telefono: String(row[12] || 'S/D'),
    zonaEscolar: String(row[13] || ''),
    sector: String(row[14] || ''),
    director: String(row[15] || 'POR ASIGNAR'),
    hombres: Number(row[16]) || 0,
    mujeres: Number(row[17]) || 0,
    alumnos: Number(row[18]) || 0,
    grupos: Number(row[19]) || 0,
    maestros: Number(row[20]) || 0,
    administrativos: Number(row[21]) || 0,
    aulasExistentes: Number(row[22]) || 0,
    aulasEnUso: Number(row[23]) || 0,
    modalidad: mod,
    dsr: '1'
  };
});
